const input = $('Webhook').first().json;
const clause = input.body || input;

if (!clause.clause_text) {
  throw new Error('clause_text is required');
}

return [{
  json: {
    clause_instance_id: clause.clause_instance_id || 'unknown',
    clause_id: clause.clause_id || 'unknown',
    clause_text: clause.clause_text,
    run_id: clause.run_id || '',
    document_id: clause.document_id || '',
    blueprint_version_id: clause.blueprint_version_id || null,
    matter_policy_id: clause.matter_policy_id || null,
    contract_type: clause.contract_type || 'nueva_planta',
    started_at: new Date().toISOString()
  }
}];

// Get data from either Parse LLM Result (LLM path) or Hybrid Router (direct path)
let prevData;
try {
  prevData = $('Parse LLM Result').first().json;
} catch (e) {
  // Direct path - get from Hybrid Router
  prevData = $('Hybrid Router (Stage 1)').first().json;
}

let embedding = null;
try {
  embedding = $json.data?.[0]?.embedding || null;
} catch (e) {
  console.log('Embedding parse error:', e.message);
}

return [{ json: { ...prevData, clauseEmbedding: embedding } }];

const prevData = $('Parse Embedding').first().json;
let ragResults = [];

try {
  // Handle both array response and empty response
  const response = $input.first().json;
  if (Array.isArray(response)) {
    ragResults = response;
  } else if (response && typeof response === 'object') {
    // If it's an object with error, treat as empty
    ragResults = [];
  }
} catch (e) {
  console.log('RAG parse error:', e.message);
  ragResults = [];
}

// Group examples by acceptance level
const acceptableExamples = ragResults.filter(r => r.acceptance === 'ACCEPTABLE').slice(0, 2);
const passableExamples = ragResults.filter(r => r.acceptance === 'PASSABLE').slice(0, 2);
const unacceptableExamples = ragResults.filter(r => r.acceptance === 'UNACCEPTABLE').slice(0, 2);

// Format for prompt
const formatExample = (ex) => `[${ex.acceptance}] (similarity: ${(ex.similarity * 100).toFixed(0)}%)\n${ex.example_text.substring(0, 500)}...`;

const ragContext = {
  hasResults: ragResults.length > 0,
  totalFound: ragResults.length,
  acceptableExamples: acceptableExamples.map(formatExample),
  passableExamples: passableExamples.map(formatExample),
  unacceptableExamples: unacceptableExamples.map(formatExample),
  topSimilarity: ragResults[0]?.similarity || 0,
  topAcceptance: ragResults[0]?.acceptance || 'NONE'
};

return [{ json: { ...prevData, ragContext, ragResults } }];

// Enrich Policy (CG-012) - with v2→v3 adapter
// =============================================
// This node enriches the policy spec with playbook data and normalizes
// the acceptability_matrix to v3 format for consistent consumption.

// Get data from Parse RAG Results and Playbook Spec
const prevData = $('Parse RAG Results').first().json;
const family = prevData.detected_family || 'OtherUnknown';

// Get playbook spec from database response (from Get Playbook Spec node)
let playbookSpec = null;
try {
    const specResponse = $input.all()[0]?.json;
    if (Array.isArray(specResponse) && specResponse.length > 0) {
        playbookSpec = specResponse[0];
    } else if (specResponse && !Array.isArray(specResponse)) {
        playbookSpec = specResponse;
    }
} catch (e) {
    console.log('Playbook spec parse error:', e.message);
}

// -------------------------
// v2→v3 Adapter
// -------------------------
function normalizeAcceptabilityMatrix(matrix) {
    const empty = {
        acceptable: { description: '', examples: [] },
        passable: { description: '', requires_approval: '', variations: [] },
        unacceptable: { description: '', action: '', patterns: [] }
    };
    if (!matrix || typeof matrix !== 'object') return empty;

    // v3 already OK - check if patterns[0] is an object
    const hasV3 = matrix?.unacceptable?.patterns?.length &&
        typeof matrix.unacceptable.patterns[0] === 'object';
    if (hasV3) return matrix;

    // v2: arrays of strings (legacy)
    const unacceptableStrings = matrix?.unacceptable?.patterns || matrix?.unacceptable || matrix?.unacceptable_patterns || [];
    const passableStrings = matrix?.passable?.variations || matrix?.passable || matrix?.passable_variations || [];
    const acceptableStrings = matrix?.acceptable?.examples || matrix?.acceptable || matrix?.acceptable_examples || [];

    return {
        acceptable: {
            description: matrix?.acceptable?.description || '',
            examples: (Array.isArray(acceptableStrings) ? acceptableStrings : []).map((s, i) => ({
                id: `acc-legacy-${i + 1}`,
                pattern: String(s),
                example: '',
                reason: 'requires playbook_specs data',
                risk_level: 'NONE'
            }))
        },
        passable: {
            description: matrix?.passable?.description || '',
            requires_approval: matrix?.passable?.requires_approval || '',
            variations: (Array.isArray(passableStrings) ? passableStrings : []).map((s, i) => ({
                id: `pas-legacy-${i + 1}`,
                pattern: String(s),
                condition: '',
                example: '',
                reason: 'requires playbook_specs data',
                risk_level: 'MEDIUM'
            }))
        },
        unacceptable: {
            description: matrix?.unacceptable?.description || '',
            action: matrix?.unacceptable?.action || 'REJECT',
            patterns: (Array.isArray(unacceptableStrings) ? unacceptableStrings : []).map((s, i) => ({
                id: `unacc-legacy-${i + 1}`,
                pattern: String(s),
                example: '',
                reason: 'requires playbook_specs data',
                risk_level: 'CRITICAL'
            }))
        }
    };
}

// Build policySpec from database data or fallback
let policySpec;
if (playbookSpec && playbookSpec.family_id) {
    // Normalize the matrix to v3
    const matrixV3 = normalizeAcceptabilityMatrix(playbookSpec.acceptability_matrix);

    policySpec = {
        clause_family: playbookSpec.family_id,
        display_name: playbookSpec.display_name,
        priority: playbookSpec.priority,
        requires_legal_review: playbookSpec.requires_legal_review,
        rule_id: `PB:v2026-02:${playbookSpec.family_id}-Core`,
        has_policy_spec: true,

        // Amazon position data
        amazon_position: playbookSpec.amazon_position,
        standard_position: {
            text: playbookSpec.amazon_position?.summary || '',
            summary: playbookSpec.amazon_position?.summary || '',
            core_requirements: playbookSpec.amazon_position?.core_requirements || []
        },

        // Acceptability data (v3 normalized)
        acceptability_matrix: matrixV3,

        // v3 objects for advanced consumers (Paranoid, Valuator)
        unacceptable_patterns: matrixV3.unacceptable.patterns,
        passable_variations: matrixV3.passable.variations,
        acceptable_examples: matrixV3.acceptable.examples,

        // Flat labels for compatibility/logging/UI
        unacceptable_pattern_labels: matrixV3.unacceptable.patterns.map(p => p.pattern),
        passable_variation_labels: matrixV3.passable.variations.map(v => v.pattern),
        acceptable_example_labels: matrixV3.acceptable.examples.map(e => e.pattern),

        // Negotiation and risk
        negotiation_guidance: playbookSpec.negotiation_guidance,
        risk_assessment: playbookSpec.risk_assessment,
        detection_patterns: playbookSpec.detection_patterns,

        // Policies
        analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
        required: true,
        routing_policy: {
            type: playbookSpec.priority === 'CRITICAL' ? 'ESCALATE_IF_UNACCEPTABLE' : 'LOG_ONLY',
            block_export: playbookSpec.priority === 'CRITICAL'
        },
        decision_policy: {
            anchor_conf_threshold: 0.85,
            gating_logic: 'STANDARD',
            block_export_if_escalated: playbookSpec.priority === 'CRITICAL'
        }
    };
} else {
    // Fallback for families without playbook spec
    policySpec = {
        id: null,
        rule_id: `default:${family}`,
        clause_family: family,
        required: true,
        analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
        standard_position: { text: 'Not defined', summary: 'Manual review required' },
        acceptability_matrix: normalizeAcceptabilityMatrix(null),
        unacceptable_patterns: [],
        passable_variations: [],
        acceptable_examples: [],
        unacceptable_pattern_labels: [],
        passable_variation_labels: [],
        acceptable_example_labels: [],
        routing_policy: { type: 'ESCALATE', block_export: true },
        decision_policy: { anchor_conf_threshold: 0.85, gating_logic: 'STANDARD', block_export_if_escalated: true },
        has_policy_spec: false
    };
}

const TH_ANCHOR = policySpec.decision_policy?.anchor_conf_threshold || 0.85;
const TH_CONF = 0.80;

return [{ json: { ...prevData, policySpec, playbookSpec, TH_ANCHOR, TH_CONF } }];

// ================================================================================
// Build Family Prompt v3.0 (PARANOID v3.0 Specification)
// ================================================================================
// Implements Legal Team specification from docs/Legal_Review_RAG_Tests.md:
// - 4 Operating Modes: FULL_PLAYBOOK, LIMITED_PLAYBOOK, RAG_ONLY, BLIND
// - Graduated Severity: CRITICAL (10), MAJOR (7), MINOR (3)
// - Industry Carve-outs with severity reduction
// - RAG Fallback Mode with similarity thresholds
// ================================================================================

const data = $('Enrich Policy').first().json;
const family = data.policySpec?.clause_family || 'OtherUnknown';
const clauseText = data.clause_text;
const policySpec = data.policySpec || {};
const playbookSpec = data.playbookSpec;
const ragContext = data.ragContext || {};

// ================================================================================
// v3.0: INDUSTRY CARVE-OUTS REGISTRY
// ================================================================================
const INDUSTRY_CARVEOUTS = {
    Entertainment: [
        { pattern: "financing sources", context: "disclosure to financing sources and completion guarantors", reduction: "MAJOR_TO_MINOR" },
        { pattern: "completion guarantors", context: "disclosure to insurers and completion guarantors", reduction: "MAJOR_TO_MINOR" },
        { pattern: "talent unavailability", context: "Including talent death, disability, or unavailability", reduction: "MAJOR_TO_MINOR" },
        { pattern: "production subsidiary", context: "Assignment to any wholly-owned production subsidiary", reduction: "MAJOR_TO_MINOR" }
    ],
    Technology: [
        { pattern: "merger or acquisition", context: "May assign without consent in connection with merger", reduction: "MAJOR_TO_MINOR" },
        { pattern: "consequential damages", context: "Neither party liable for consequential, incidental damages", reduction: "NO_FLAG", condition: "mutual" }
    ],
    Financial: [
        { pattern: "required by applicable law", context: "Disclosure required by applicable law or regulation", reduction: "NO_FLAG" },
        { pattern: "affiliate within", context: "Assignment to any affiliate within same holding company", reduction: "MAJOR_TO_MINOR" }
    ],
    RealEstate: [
        { pattern: "weather conditions", context: "Including unusually severe weather conditions", reduction: "NO_FLAG" },
        { pattern: "permit delays", context: "Delays in obtaining governmental permits", reduction: "NO_FLAG" }
    ]
};

// ================================================================================
// v3.0: DETERMINE OPERATING MODE
// ================================================================================
function determineOperatingMode(playbookSpec, ragContext) {
    const hasPlaybook = !!(playbookSpec && playbookSpec.amazon_position);
    const hasFullMatrix = !!(playbookSpec?.acceptability_matrix?.unacceptable?.patterns?.length);
    const hasRag = !!(ragContext && Object.keys(ragContext).length > 0);

    if (hasPlaybook && hasFullMatrix) return 'FULL_PLAYBOOK';
    if (hasPlaybook && !hasFullMatrix && hasRag) return 'LIMITED_PLAYBOOK';
    if (!hasPlaybook && hasRag) return 'RAG_ONLY';
    return 'BLIND';
}

// ================================================================================
// FORMATTERS
// ================================================================================
function formatGraduatedRedFlags(critical = [], major = [], minor = []) {
    let out = '';

    if (critical.length) {
        out += '\nRED FLAGS — CRITICAL (Severity: 10)\nImmediate escalation required. Cannot be mitigated.\n';
        out += critical.map(f => `  • "${f}"`).join('\n');
    }

    if (major.length) {
        out += '\n\nRED FLAGS — MAJOR (Severity: 7)\nEscalate unless mitigated by another clause provision.\n';
        out += major.map(f => `  • "${f}"`).join('\n');
    }

    if (minor.length) {
        out += '\n\nRED FLAGS — MINOR (Severity: 3)\nFlag and document, but may be approved with notes.\n';
        out += minor.map(f => `  • "${f}"`).join('\n');
    }

    return out || '  • None defined';
}

function formatIndustryCarveouts(carveouts = []) {
    if (!carveouts.length) return '  • None defined for this family';
    return carveouts.map(c =>
        `  • [${c.industry}] "${c.pattern}" → ${c.reduction}\n    Context: ${c.context}`
    ).join('\n');
}

function formatUnacceptable(patterns = []) {
    if (!Array.isArray(patterns) || !patterns.length) return '  • None defined';
    return patterns.map(p => {
        if (!p || typeof p !== 'object') return `  • ${String(p)}`;
        return [
            `  • [${p.id || 'unacc'}] ${p.pattern || ''}`,
            p.example ? `    Example: "${p.example}"` : null,
            p.reason ? `    Reason: ${p.reason}` : null,
            p.risk_level ? `    Risk: ${p.risk_level}` : null,
        ].filter(Boolean).join('\n');
    }).join('\n');
}

function formatPassable(vars = []) {
    if (!Array.isArray(vars) || !vars.length) return '  • None defined';
    return vars.map(v => {
        if (!v || typeof v !== 'object') return `  • ${String(v)}`;
        return [
            `  • [${v.id || 'pas'}] ${v.pattern || v.variation || ''}`,
            v.condition ? `    Condition: ${v.condition}` : null,
            v.risk_level ? `    Risk: ${v.risk_level}` : null,
        ].filter(Boolean).join('\n');
    }).join('\n');
}

function formatAcceptable(examples = []) {
    if (!Array.isArray(examples) || !examples.length) return '  • None defined';
    return examples.slice(0, 3).map(e => {
        if (!e || typeof e !== 'object') return `  • ${String(e)}`;
        return `  • [${e.id || 'acc'}] ${e.pattern || ''}`;
    }).join('\n');
}

function formatMustHave(anchors = []) {
    if (!Array.isArray(anchors) || !anchors.length) return '  • None defined';
    return anchors.map(a => `  • "${a}"`).join('\n');
}

function formatCoreRequirements(reqs = []) {
    if (!Array.isArray(reqs) || !reqs.length) return '  • None defined';
    return reqs.map(r => `  • ${r}`).join('\n');
}

function formatRagExamples(rag = {}) {
    const topUnacc = (rag.unacceptableExamples || rag.unacceptable || []).slice(0, 2);
    const topAcc = (rag.acceptableExamples || rag.acceptable || []).slice(0, 1);
    const topPass = (rag.passableExamples || rag.passable || []).slice(0, 1);

    let out = '';
    if (topUnacc.length) {
        out += '\n  UNACCEPTABLE examples (for grounding):\n';
        out += topUnacc.map((e, i) => `    ${i + 1}. ${String(e.example_text || e.text || e).slice(0, 400)}...`).join('\n');
    }
    if (topAcc.length) {
        out += '\n  ACCEPTABLE examples (for grounding):\n';
        out += topAcc.map((e, i) => `    ${i + 1}. ${String(e.example_text || e.text || e).slice(0, 400)}...`).join('\n');
    }
    if (topPass.length) {
        out += '\n  PASSABLE examples (for grounding):\n';
        out += topPass.map((e, i) => `    ${i + 1}. ${String(e.example_text || e.text || e).slice(0, 400)}...`).join('\n');
    }

    return out || '  • No RAG examples available';
}

// ================================================================================
// BUILD PROMPTS
// ================================================================================
const operatingMode = determineOperatingMode(playbookSpec, ragContext);
let paranoidSystem, valuatorSystem, TH_ANCHOR;

// Get industry carve-outs for this family
const familyCarveouts = playbookSpec?.industry_carveouts || [];
const allCarveouts = Object.values(INDUSTRY_CARVEOUTS).flat();

if (playbookSpec && playbookSpec.amazon_position) {
    const pos = playbookSpec.amazon_position || {};
    const matrix = playbookSpec.acceptability_matrix || {};
    const detection = playbookSpec.detection_patterns || {};

    // v3.0: Get graduated red flags
    const criticalFlags = playbookSpec.critical_red_flags || [];
    const majorFlags = playbookSpec.major_red_flags || detection.red_flags || [];
    const minorFlags = playbookSpec.minor_red_flags || [];

    // PARANOID SYSTEM PROMPT v3.0
    paranoidSystem = `PARANOID ANALYSIS AGENT — ${playbookSpec.display_name}
Version: 3.0 | Family: ${playbookSpec.family_id} | Priority: ${playbookSpec.priority}
Mode: ${operatingMode}

═══════════════════════════════════════════════════════════════
SECTION 1: MISSION AND PHILOSOPHY
═══════════════════════════════════════════════════════════════

YOUR MISSION
You must identify EVERY deviation, risk, or concern with HIGH RECALL.
However, you must CLASSIFY findings by severity to enable graduated response.

OPERATING MODES
Your behavior adapts based on available reference data:
- FULL_PLAYBOOK: Complete playbook_spec available. Apply all matching rules.
- LIMITED_PLAYBOOK: Partial playbook_spec. Apply available rules + RAG fallback.
- RAG_ONLY: No playbook_spec but RAG examples exist. Rely on similarity matching.
- BLIND: No playbook_spec and no RAG examples. Flag everything, escalate all.

Current mode: ${operatingMode}

═══════════════════════════════════════════════════════════════
SECTION 2: REFERENCE DATA
═══════════════════════════════════════════════════════════════

AMAZON STANDARD POSITION
${pos.summary || 'Not defined for this family'}

CORE REQUIREMENTS
${formatCoreRequirements(pos.core_requirements)}

MUST-HAVE ANCHORS (required textual elements)
${formatMustHave(detection.must_have)}

═══════════════════════════════════════════════════════════════
SECTION 3: RED FLAGS (GRADUATED SEVERITY)
═══════════════════════════════════════════════════════════════

${formatGraduatedRedFlags(criticalFlags, majorFlags, minorFlags)}

Severity scoring:
- Total severity >= 10 → risk_level = RED
- Total severity 5-9 → risk_level = YELLOW
- Total severity < 5 → risk_level = GREEN (if no other issues)

═══════════════════════════════════════════════════════════════
SECTION 4: PATTERN MATCHING
═══════════════════════════════════════════════════════════════

UNACCEPTABLE PATTERNS (must reject if matched)
${formatUnacceptable(matrix?.unacceptable?.patterns)}

PASSABLE VARIATIONS (acceptable with legal approval)
${formatPassable(matrix?.passable?.variations)}

ACCEPTABLE EXAMPLES (fully compliant language)
${formatAcceptable(matrix?.acceptable?.examples)}

═══════════════════════════════════════════════════════════════
SECTION 5: INDUSTRY-STANDARD CARVE-OUTS
═══════════════════════════════════════════════════════════════

The following patterns are commonly accepted in specific industries.
When detected, flag as MINOR (not MAJOR/CRITICAL) and note the carve-out.

${formatIndustryCarveouts(familyCarveouts.length ? familyCarveouts : allCarveouts.slice(0, 8))}

When a clause matches an INDUSTRY-STANDARD CARVE-OUT:
1. Set industry_carveout = true in the observation
2. Reduce severity by 4 points (e.g., MAJOR → MINOR equivalent)
3. Include carve-out reference in the reason field
4. Do NOT auto-escalate solely due to the carve-out pattern

═══════════════════════════════════════════════════════════════
SECTION 6: RAG FALLBACK MODE
═══════════════════════════════════════════════════════════════

When operating in LIMITED_PLAYBOOK or RAG_ONLY mode:
- If similarity >= 0.92 with ACCEPTABLE example AND no CRITICAL flags:
  → May set risk_level = GREEN with rag_supported = true
- If similarity >= 0.85 with ACCEPTABLE example AND no CRITICAL flags:
  → Set risk_level = YELLOW with rag_supported = true
- If similarity >= 0.85 with UNACCEPTABLE example:
  → Confirm risk_level = RED, cite the historical rejection

═══════════════════════════════════════════════════════════════
SECTION 7: MATCHING RULES (DETERMINISTIC)
═══════════════════════════════════════════════════════════════

- Match is case-insensitive and whitespace-tolerant
- evidence MUST be an exact substring from clause_text
- offsets are 0-indexed character positions in clause_text
- If a must-have is missing: evidence = "[missing: <anchor>]", offsets = {start:0, end:0}

═══════════════════════════════════════════════════════════════
SECTION 8: OUTPUT FORMAT
═══════════════════════════════════════════════════════════════

Return ONLY valid JSON matching this schema:

{
  "mode": "${operatingMode}",

  "observations": [
    {
      "evidence": "exact substring from clause_text OR [missing: <anchor>]",
      "offsets": { "start": 0, "end": 0 },
      "change_type": "missing|added|modified",
      "possible_category": "MatchesUnacceptable|MissingRequired|PassableVariation|IndustryCarveout|UnknownChange",
      "pattern_matched": "red_flag name OR pattern name OR null",
      "severity_class": "CRITICAL|MAJOR|MINOR",
      "severity_score": 0,
      "industry_carveout": false,
      "carveout_reference": "string or null",
      "mitigated_by": "string describing mitigation or null",
      "confidence": 0.0,
      "reason": "brief explanation",
      "playbook_reference": "pattern id or null"
    }
  ],

  "rag_matches": [
    {
      "example_id": "uuid",
      "similarity": 0.0,
      "acceptability_status": "ACCEPTABLE|PASSABLE|UNACCEPTABLE",
      "historical_notes": "string or null"
    }
  ],

  "summary": {
    "counts": {
      "total": 0,
      "critical": 0,
      "major": 0,
      "minor": 0,
      "missing": 0,
      "added": 0,
      "modified": 0
    },
    "total_severity_score": 0,
    "coverage_confidence": 0.0,
    "red_flags_found": 0,
    "unacceptable_patterns_found": 0,
    "must_have_missing": 0,
    "industry_carveouts_applied": 0,
    "rag_supported": false,
    "highest_rag_similarity": 0.0
  },

  "risk_level": "RED|YELLOW|GREEN",

  "risk_level_reasoning": "One sentence explaining why this risk level was assigned"
}`;

    // VALUATOR prompt remains similar but with v3.0 context
    valuatorSystem = `VALUATOR AGENT — ${playbookSpec.display_name}
Version: 3.0 | Mode: MODE_ENUMERATED_DEVIATIONS | Priority: ${playbookSpec.priority}

YOUR MISSION
Based on Paranoid observations, determine final_status and propose changes.

RULES
1. NO NEW TEXT - proposed replacement_text MUST come from playbook standard_position
2. DETERMINISTIC MAPPING:
   - observations contains CRITICAL severity → final_status = UnacceptableDeviation
   - observations contains unmitigated MAJOR (>=2) → final_status = UnacceptableDeviation
   - observations only MINOR or IndustryCarveout → final_status = AcceptableDeviation
   - observations empty AND risk_level=GREEN → final_status = Compliant
3. RAG-SUPPORTED APPROVAL:
   - If rag_supported = true AND no CRITICAL → may approve with notes
4. ESCALATE ON UNCERTAINTY - if coverage_confidence < 0.75 → escalation_recommended = true

OUTPUT FORMAT (JSON ONLY):
{
  "final_status": "Compliant|AcceptableDeviation|UnacceptableDeviation|Ambiguous",
  "escalation_recommended": false,
  "escalation_reason": null,
  "proposed_changes": [...],
  "confidence_overall": 0.0
}`;

    // v3.0: Relaxed thresholds
    const thresholds = {
        CRITICAL: { auto_pass: 0.90, with_notes: 0.80 },
        HIGH: { auto_pass: 0.88, with_notes: 0.78 },
        MEDIUM: { auto_pass: 0.85, with_notes: 0.75 },
        LOW: { auto_pass: 0.80, with_notes: 0.70 }
    };
    TH_ANCHOR = thresholds[playbookSpec.priority]?.auto_pass || 0.85;

} else {
    // RAG_ONLY or BLIND mode
    paranoidSystem = `PARANOID ANALYSIS AGENT — ${family}
Family: ${family} | Mode: ${operatingMode}

This clause family lacks playbook specification. 
${operatingMode === 'RAG_ONLY' ? 'Using RAG examples for grounding.' : 'No grounding available - full escalation mode.'}

ANALYZE FOR:
1. Party obligations and responsibilities
2. Timelines and conditions
3. Exclusions and limitations
4. Any unusual or concerning language

OUTPUT FORMAT: Same as FULL_PLAYBOOK mode with mode="${operatingMode}"`;

    valuatorSystem = `VALUATOR AGENT — ${family}
Mode: ${operatingMode}

RULES:
1. In RAG_ONLY mode with high-similarity match to ACCEPTABLE → may approve
2. In BLIND mode → always escalate
3. No proposed_changes without standard_position

OUTPUT FORMAT:
{
  "final_status": "Compliant|AcceptableDeviation|UnacceptableDeviation|Ambiguous",
  "escalation_recommended": ${operatingMode === 'BLIND'},
  "escalation_reason": "${operatingMode === 'BLIND' ? 'BLIND mode - no reference data' : null}",
  "proposed_changes": [],
  "confidence_overall": 0.0
}`;

    TH_ANCHOR = 0.85;
}

// Build User Message with RAG context
const ragBlock = `
RAG CONTEXT (for grounding only — evidence must come from clause_text):
${formatRagExamples(ragContext)}`;

const paranoidUserMessage = `CLAUSE TEXT TO ANALYZE:
---
${clauseText}
---

${ragBlock}

INSTRUCTIONS:
1. Check for ALL red flags (CRITICAL first, then MAJOR, then MINOR)
2. Check for ALL must-have anchors (report missing ones)
3. Check for industry carve-outs that may reduce severity
4. Check for unacceptable/passable patterns

Report EVERY finding with severity_class and severity_score.
RESPOND ONLY WITH JSON.`;

// Build complete messages for OpenAI
const paranoidMessages = [
    { role: 'system', content: paranoidSystem },
    { role: 'user', content: paranoidUserMessage }
];

return [{
    json: {
        ...data,
        paranoidMessages,
        paranoidSystemPrompt: paranoidSystem,
        paranoidUserPrompt: paranoidUserMessage,
        valuatorSystemPrompt: valuatorSystem,
        TH_ANCHOR: TH_ANCHOR,
        usedDynamicPrompt: !!playbookSpec,
        promptVersion: '3.0',
        operatingMode: operatingMode,
        ragInjected: !!(ragContext && Object.keys(ragContext).length)
    }
}];

// ================================================================================
// Parse Paranoid v3.0 (Output Parser for Paranoid Agent v3.0)
// ================================================================================
// Handles the new v3.0 output format with graduated severity and RAG matches
// ================================================================================

const prev = $('Build Family Prompt').first().json || {};
const clauseText = String(prev.clause_text || '');
const playbookSpec = prev.playbookSpec || {};
const operatingMode = prev.operatingMode || 'BLIND';

const detection = playbookSpec.detection_patterns || {};

// v3.0: Get graduated red flags from playbook_spec
const criticalFlags = playbookSpec.critical_red_flags || [];
const majorFlags = playbookSpec.major_red_flags || detection.red_flags || [];
const minorFlags = playbookSpec.minor_red_flags || [];

// ─────────────────────────────────────────────────────────────
// PARSE LLM OUTPUT
// ─────────────────────────────────────────────────────────────
let parsed = {
    mode: operatingMode,
    observations: [],
    rag_matches: [],
    summary: {
        counts: { total: 0, critical: 0, major: 0, minor: 0, missing: 0, added: 0, modified: 0 },
        total_severity_score: 0,
        coverage_confidence: 0,
        red_flags_found: 0,
        unacceptable_patterns_found: 0,
        must_have_missing: 0,
        industry_carveouts_applied: 0,
        rag_supported: false,
        highest_rag_similarity: 0
    },
    risk_level: 'GREEN',
    risk_level_reasoning: ''
};

let validationErrors = [];

try {
    const raw = $json.choices?.[0]?.message?.content || '{}';
    // Clean markdown code blocks if present
    let cleaned = raw.trim();
    if (cleaned.startsWith('```')) {
        cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
    }
    parsed = { ...parsed, ...JSON.parse(cleaned) };
} catch (e) {
    validationErrors.push({
        field: 'json_parse',
        error: e.message,
        auto_fixed: false
    });
}

// ─────────────────────────────────────────────────────────────
// ENSURE ARRAYS EXIST
// ─────────────────────────────────────────────────────────────
if (!Array.isArray(parsed.observations)) {
    parsed.observations = [];
    validationErrors.push({ field: 'observations', error: 'Not an array', auto_fixed: true });
}

if (!Array.isArray(parsed.rag_matches)) {
    parsed.rag_matches = [];
}

// ─────────────────────────────────────────────────────────────
// AUTO-FIX: Missing offsets
// ─────────────────────────────────────────────────────────────
const lowerText = clauseText.toLowerCase();
let offsetsFixed = 0;

parsed.observations = parsed.observations.map((obs, idx) => {
    // Ensure required fields exist
    if (!obs.severity_class) {
        obs.severity_class = 'MAJOR'; // Default conservative
    }
    if (obs.severity_score === undefined) {
        obs.severity_score = obs.severity_class === 'CRITICAL' ? 10 :
            obs.severity_class === 'MAJOR' ? 7 : 3;
    }

    // Fix missing or invalid offsets
    if (!obs.offsets || typeof obs.offsets.start !== 'number') {
        const evidence = String(obs.evidence || '').toLowerCase();
        if (evidence && !evidence.startsWith('[missing:')) {
            const startIdx = lowerText.indexOf(evidence);
            if (startIdx >= 0) {
                obs.offsets = { start: startIdx, end: startIdx + evidence.length };
                offsetsFixed++;
            } else {
                obs.offsets = { start: 0, end: 0 };
            }
        } else {
            obs.offsets = { start: 0, end: 0 };
        }
    }

    return obs;
});

if (offsetsFixed > 0) {
    validationErrors.push({
        field: 'offsets',
        error: `${offsetsFixed} observations had missing offsets`,
        auto_fixed: true
    });
}

// ─────────────────────────────────────────────────────────────
// DETERMINISTIC RED FLAG DETECTION (backup)
// ─────────────────────────────────────────────────────────────
let redFlagHits = [];

// Check CRITICAL flags
criticalFlags.forEach(flag => {
    const flagLower = String(flag).toLowerCase();
    const idx = lowerText.indexOf(flagLower);
    if (idx >= 0) {
        redFlagHits.push({
            pattern: flag,
            severity_class: 'CRITICAL',
            severity_score: 10,
            idx: idx,
            len: flagLower.length
        });
    }
});

// Check MAJOR flags
majorFlags.forEach(flag => {
    const flagLower = String(flag).toLowerCase();
    const idx = lowerText.indexOf(flagLower);
    if (idx >= 0) {
        redFlagHits.push({
            pattern: flag,
            severity_class: 'MAJOR',
            severity_score: 7,
            idx: idx,
            len: flagLower.length
        });
    }
});

// Check MINOR flags
minorFlags.forEach(flag => {
    const flagLower = String(flag).toLowerCase();
    const idx = lowerText.indexOf(flagLower);
    if (idx >= 0) {
        redFlagHits.push({
            pattern: flag,
            severity_class: 'MINOR',
            severity_score: 3,
            idx: idx,
            len: flagLower.length
        });
    }
});

// Add detected red flags as observations if not already present
redFlagHits.forEach(hit => {
    const alreadyReported = parsed.observations.some(obs => {
        if (!obs.offsets) return false;
        // Check overlap
        return (obs.offsets.start <= hit.idx && obs.offsets.end > hit.idx) ||
            (hit.idx <= obs.offsets.start && hit.idx + hit.len > obs.offsets.start);
    });

    if (!alreadyReported) {
        parsed.observations.push({
            evidence: clauseText.substring(hit.idx, hit.idx + hit.len),
            offsets: { start: hit.idx, end: hit.idx + hit.len },
            change_type: 'added',
            possible_category: 'MatchesRedFlag',
            pattern_matched: hit.pattern,
            severity_class: hit.severity_class,
            severity_score: hit.severity_score,
            industry_carveout: false,
            carveout_reference: null,
            mitigated_by: null,
            confidence: 0.95,
            reason: `Deterministic red flag detection: "${hit.pattern}"`,
            playbook_reference: null
        });

        validationErrors.push({
            field: 'red_flag_injection',
            error: `Added missed ${hit.severity_class} red flag: "${hit.pattern}"`,
            auto_fixed: true
        });
    }
});

// ─────────────────────────────────────────────────────────────
// CHECK MUST-HAVE ANCHORS
// ─────────────────────────────────────────────────────────────
const mustHave = Array.isArray(detection.must_have) ? detection.must_have : [];

mustHave.forEach(anchor => {
    const anchorLower = String(anchor).toLowerCase();
    const found = lowerText.includes(anchorLower);

    if (!found) {
        // Check if already reported
        const alreadyReported = parsed.observations.some(obs =>
            obs.evidence && obs.evidence.toLowerCase().includes(`[missing: ${anchor.toLowerCase()}]`)
        );

        if (!alreadyReported) {
            parsed.observations.push({
                evidence: `[missing: ${anchor}]`,
                offsets: { start: 0, end: 0 },
                change_type: 'missing',
                possible_category: 'MissingRequired',
                pattern_matched: anchor,
                severity_class: 'MAJOR',
                severity_score: 7,
                industry_carveout: false,
                carveout_reference: null,
                mitigated_by: null,
                confidence: 1.0,
                reason: `Required anchor "${anchor}" not found in clause text`,
                playbook_reference: null
            });
        }
    }
});

// ─────────────────────────────────────────────────────────────
// RECALCULATE SUMMARY
// ─────────────────────────────────────────────────────────────
const counts = {
    total: parsed.observations.length,
    critical: parsed.observations.filter(o => o.severity_class === 'CRITICAL').length,
    major: parsed.observations.filter(o => o.severity_class === 'MAJOR').length,
    minor: parsed.observations.filter(o => o.severity_class === 'MINOR').length,
    missing: parsed.observations.filter(o => o.change_type === 'missing').length,
    added: parsed.observations.filter(o => o.change_type === 'added').length,
    modified: parsed.observations.filter(o => o.change_type === 'modified').length
};

const totalSeverityScore = parsed.observations.reduce(
    (sum, obs) => sum + (obs.severity_score || 0),
    0
);

const industryCarveoutsApplied = parsed.observations.filter(
    o => o.industry_carveout
).length;

const highestRagSimilarity = parsed.rag_matches.length > 0
    ? Math.max(...parsed.rag_matches.map(m => m.similarity || 0))
    : 0;

parsed.summary = {
    counts,
    total_severity_score: totalSeverityScore,
    coverage_confidence: parsed.summary.coverage_confidence ||
        (parsed.observations.length > 0 ? 0.8 : 0.9),
    red_flags_found: counts.critical + counts.major,
    unacceptable_patterns_found: parsed.observations.filter(
        o => o.possible_category === 'MatchesUnacceptable'
    ).length,
    must_have_missing: counts.missing,
    industry_carveouts_applied: industryCarveoutsApplied,
    rag_supported: highestRagSimilarity >= 0.85,
    highest_rag_similarity: highestRagSimilarity
};

// ─────────────────────────────────────────────────────────────
// DETERMINE RISK LEVEL (deterministic override)
// ─────────────────────────────────────────────────────────────
let calculatedRiskLevel = 'GREEN';
let riskReasoning = '';

if (counts.critical > 0) {
    calculatedRiskLevel = 'RED';
    riskReasoning = `${counts.critical} CRITICAL severity issue(s) detected`;
} else if (totalSeverityScore >= 10) {
    calculatedRiskLevel = 'RED';
    riskReasoning = `Total severity score ${totalSeverityScore} >= 10 threshold`;
} else if (totalSeverityScore >= 5 || counts.major > 0) {
    calculatedRiskLevel = 'YELLOW';
    riskReasoning = `Severity score ${totalSeverityScore} or ${counts.major} MAJOR issue(s)`;
} else if (counts.minor > 0) {
    calculatedRiskLevel = 'GREEN';
    riskReasoning = `Only ${counts.minor} MINOR issue(s), no MAJOR/CRITICAL`;
} else {
    calculatedRiskLevel = 'GREEN';
    riskReasoning = 'No issues detected';
}

// Override if LLM's assessment is more severe
if (parsed.risk_level === 'RED' && calculatedRiskLevel !== 'RED') {
    // Trust LLM if it's more cautious, but log it
    validationErrors.push({
        field: 'risk_level',
        error: `LLM reported RED but calculation shows ${calculatedRiskLevel}`,
        auto_fixed: false
    });
} else {
    parsed.risk_level = calculatedRiskLevel;
    parsed.risk_level_reasoning = riskReasoning;
}

// ─────────────────────────────────────────────────────────────
// BUILD OUTPUT
// ─────────────────────────────────────────────────────────────
return [{
    json: {
        ...prev,
        paranoidOutput: parsed,
        validationErrors: validationErrors,
        parseVersion: '3.0',
        // Summary for logging
        _parseSummary: {
            observations_count: parsed.observations.length,
            critical_count: counts.critical,
            major_count: counts.major,
            minor_count: counts.minor,
            total_severity: totalSeverityScore,
            risk_level: parsed.risk_level,
            rag_supported: parsed.summary.rag_supported,
            auto_fixes_applied: validationErrors.filter(e => e.auto_fixed).length,
            mode: operatingMode
        }
    }
}];

