// 1. Validate "No new text" - each change must have source_reference
for (const change of data.valuatorOutput?.proposed_changes || []) {
  if (change.op_type === 'INSERT' || change.op_type === 'REPLACE') {
    if (!change.source_reference?.exact_text) {
      errors.push({ 
        type: 'NO_SOURCE_REFERENCE', 
        change_id: change.change_id || 'unknown',
        message: 'Cambio sin source_reference'
      });
      passed = false;
    }
  }
}

